-- Warehouse for corpus northwind-golden-v1. Generated by corpus-gen/generate.ts; do not edit.
-- Empty tables: Metabase only needs the schema to sync. Re-running drops and recreates the schema.
DROP SCHEMA IF EXISTS analytics CASCADE;
CREATE SCHEMA analytics;

CREATE TABLE analytics.fct_orders_v2 (
  order_line_id bigint,
  order_id bigint,
  customer_id bigint,
  sku text,
  channel text,
  currency text,
  quantity int,
  net_amount numeric(12,2),
  net_amount_eur numeric(12,2),
  discount_code text,
  ordered_at timestamptz
);
COMMENT ON TABLE analytics.fct_orders_v2 IS 'Order line facts, one row per order line. Includes net amount after discounts and refunds, channel, currency and FX-converted EUR amount. Replaced fct_orders in 2025.';
CREATE TABLE analytics.fct_orders (
  order_id bigint,
  customer_id bigint,
  gross_amount numeric(12,2),
  created_at timestamptz
);
COMMENT ON TABLE analytics.fct_orders IS 'DEPRECATED. Legacy order header table, gross amounts only. Use fct_orders_v2.';
CREATE TABLE analytics.dim_customer (
  customer_id bigint,
  email_hash text,
  country text,
  acquisition_channel text,
  signup_at timestamptz,
  lifetime_orders int
);
COMMENT ON TABLE analytics.dim_customer IS 'One row per customer account, with signup date, country, acquisition channel and lifetime order count.';
CREATE TABLE analytics.dim_product (
  sku text,
  name text,
  category text,
  season text,
  cost_price numeric(10,2),
  list_price numeric(10,2)
);
COMMENT ON TABLE analytics.dim_product IS 'Product catalog: SKU, category, season, cost price and list price.';
CREATE TABLE analytics.fct_returns (
  rma_number text,
  order_line_id bigint,
  reason_code text,
  refund_amount numeric(12,2),
  returned_at timestamptz
);
COMMENT ON TABLE analytics.fct_returns IS 'Returned order lines with RMA number, return reason code and refund amount.';
CREATE TABLE analytics.fct_web_sessions (
  session_id text,
  customer_id bigint,
  landing_page text,
  utm_source text,
  device text,
  converted boolean,
  started_at timestamptz
);
COMMENT ON TABLE analytics.fct_web_sessions IS 'Clickstream sessions from the web shop, with landing page, UTM source and whether the session converted.';
CREATE TABLE analytics.fct_marketing_spend (
  spend_date date,
  channel text,
  campaign text,
  spend_eur numeric(12,2),
  impressions bigint,
  clicks bigint
);
COMMENT ON TABLE analytics.fct_marketing_spend IS 'Daily paid media spend by channel and campaign (Google, Meta, TikTok, affiliates).';
CREATE TABLE analytics.fct_support_tickets (
  ticket_id bigint,
  customer_id bigint,
  category text,
  priority text,
  first_response_minutes int,
  resolution_minutes int,
  created_at timestamptz
);
COMMENT ON TABLE analytics.fct_support_tickets IS 'Zendesk tickets with category, priority, first response time and resolution time.';
CREATE TABLE analytics.fct_shipments (
  shipment_id bigint,
  order_id bigint,
  carrier text,
  warehouse_id int,
  promised_date date,
  delivered_date date,
  cost_eur numeric(10,2)
);
COMMENT ON TABLE analytics.fct_shipments IS 'Parcels handed to carriers (DHL, InPost, Yamato, UPS) with promised and actual delivery dates.';
CREATE TABLE analytics.dim_warehouse (
  warehouse_id int,
  name text,
  city text,
  country text
);
COMMENT ON TABLE analytics.dim_warehouse IS 'Distribution centres: Poznań, Rotterdam, Reno and Chiba.';
CREATE TABLE analytics.fct_inventory_snapshot (
  snapshot_date date,
  sku text,
  warehouse_id int,
  on_hand_units int,
  inbound_units int
);
COMMENT ON TABLE analytics.fct_inventory_snapshot IS 'Daily on-hand stock per SKU per warehouse.';
CREATE TABLE analytics.fct_subscriptions (
  subscription_id bigint,
  customer_id bigint,
  plan text,
  monthly_price_eur numeric(8,2),
  started_at timestamptz,
  cancelled_at timestamptz,
  cancel_reason text
);
COMMENT ON TABLE analytics.fct_subscriptions IS 'Trail Club membership subscriptions: start, cancel date, plan and monthly price.';
CREATE TABLE analytics.hr_employees (
  employee_id int,
  department text,
  location text,
  manager_id int,
  start_date date
);
COMMENT ON TABLE analytics.hr_employees IS 'Employee roster from the HRIS: department, location, start date, manager.';
CREATE TABLE analytics.hr_terminations (
  employee_id int,
  termination_date date,
  voluntary boolean
);
COMMENT ON TABLE analytics.hr_terminations IS 'Leavers with termination date and voluntary or involuntary flag.';
CREATE TABLE analytics.fct_payments (
  payment_id text,
  order_id bigint,
  method text,
  amount_eur numeric(12,2),
  fee_eur numeric(10,4),
  is_chargeback boolean,
  captured_at timestamptz
);
COMMENT ON TABLE analytics.fct_payments IS 'Card and wallet payments captured through Adyen, including chargebacks and payment method.';
CREATE TABLE analytics.stg_adyen_settlements (
  psp_reference text,
  merchant_reference text,
  gross numeric(12,2),
  commission numeric(10,4),
  settled_at timestamptz
);
COMMENT ON TABLE analytics.stg_adyen_settlements IS 'Raw Adyen settlement report rows, loaded nightly. Not for reporting.';
CREATE TABLE analytics.dim_wholesale_account (
  account_id int,
  name text,
  tier text,
  credit_limit_eur numeric(12,2),
  account_manager text
);
COMMENT ON TABLE analytics.dim_wholesale_account IS 'B2B retail partners, their tier, credit limit and account manager.';
CREATE TABLE analytics.fct_wholesale_orders (
  po_number text,
  account_id int,
  amount_eur numeric(12,2),
  ship_window_start date,
  ship_window_end date,
  status text
