COMMENT ON TABLE analytics.fct_wholesale_orders IS 'Purchase orders from retail partners, with PO number and requested ship window.';
CREATE TABLE analytics.gdpr_dsr_requests (
  request_id text,
  request_type text,
  received_at timestamptz,
  completed_at timestamptz
);
COMMENT ON TABLE analytics.gdpr_dsr_requests IS 'Data subject requests (access, erasure, rectification) and their SLA status.';
CREATE TABLE analytics.fct_nps_responses (
  response_id bigint,
  customer_id bigint,
  score int,
  comment text,
  responded_at timestamptz
);
COMMENT ON TABLE analytics.fct_nps_responses IS 'Post-purchase survey responses with 0-10 score and free-text comment.';
